// Strip tags/scripts/styles down to plain text, capped so the
// DeepSeek prompt stays a reasonable size. A page that failed to
// load (onError kept the item alive with no body) becomes an empty
// string here, which the AI Guard below catches by name.
const html = $json.data || '';
const text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);

return {
  json: {
    domain: $('Discovery Webhook').first().json.body.domain,
    site_text: text,
  },
};

